	(433, 'Mantenere la calma e aspettare che la sospensione venga revocata, senza prendere decisioni affrettate.', 109, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(434, 'Vendere immediatamente qualsiasi altro titolo dello stesso emittente per paura.', 109, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(435, 'Pensare che la sospensione equivalga al fallimento.', 109, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(436, 'Comprare altre azioni dello stesso settore per compensare.', 109, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(437, 'Valutare le opzioni offerte (OPA, liquidazione) e decidere in base alla convenienza, non al panico.', 110, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(438, 'Vendere tutto subito a qualsiasi prezzo per non rimanere incastrati.', 110, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(439, 'Non fare nulla e tenere i titoli illiquidi per sempre, senza valutare alternative.', 110, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(440, 'Acquistare altri titoli della stessa azienda sperando che torni in borsa.', 110, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(441, 'Evitarle o aspettare che il titolo sia incluso negli indici, comprandolo successivamente tramite ETF.', 111, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(442, 'Partecipare a tutte le IPO perché sono l’occasione per comprare a sconto.', 111, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(443, 'Comprare IPO di aziende famose convinti che saliranno subito dopo il collocamento.', 111, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(444, 'Affidarsi ai consigli di amici che hanno guadagnato con le IPO passate.', 111, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(445, 'Sapere che non cambia il valore totale del proprio investimento, ma solo il numero di azioni e il prezzo unitario.', 112, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(446, 'Pensare che lo split azzeri il valore delle azioni vecchie.', 112, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(447, 'Vendere subito dopo uno split perché il prezzo è più basso e si possono comprare più azioni.', 112, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(448, 'Credere che lo split porti automaticamente a un aumento del valore.', 112, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(449, 'Capire che è un’operazione tecnica che non modifica il valore, non è un segnale positivo o negativo di per sé.', 113, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(450, 'Vedere il raggruppamento come un evento negativo e vendere immediatamente.', 113, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(451, 'Pensare che ora il titolo valga di più perché il prezzo unitario è salito.', 113, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(452, 'Non aggiornare il numero di azioni nel proprio foglio di calcolo, creando confusione.', 113, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(453, 'Controllare i volumi medi giornalieri e lo spread per evitare di comprare strumenti difficili da rivendere.', 114, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(454, 'Non preoccuparsi della liquidità perché in borsa si può sempre vendere tutto.', 114, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(455, 'Comprare titoli illiquidi perché spesso sono sottovalutati.', 114, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(456, 'Pensare che la liquidità riguardi solo le azioni, non gli ETF.', 114, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(457, 'Considerarlo uno strumento previdenziale con vantaggi fiscali, ma con vincoli di liquidità fino alla pensione.', 115, 1, '2026-05-08 20:52:06', '2026-05-08 23:28:08', 1, 0),
	(458, 'Trattarlo come un normale conto deposito da cui prelevare in qualsiasi momento.', 115, 0, '2026-05-08 20:52:06', '2026-05-08 23:28:08', 1, 0),
	(459, 'Non aprirlo mai perché la pensione pubblica basterà sicuramente.', 115, 0, '2026-05-08 20:52:06', '2026-05-08 23:28:08', 1, 0),
	(460, 'Versarci tutti i risparmi, anche quelli che potrebbero servire a breve, per il vantaggio fiscale.', 115, 0, '2026-05-08 20:52:06', '2026-05-08 23:28:08', 1, 0),
	(461, 'Valutare il risparmio fiscale attuale in base alla propria aliquota IRPEF e confrontarlo con i costi e i vincoli.', 116, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(462, 'Aderire al fondo pensione solo se la deduzione azzera completamente le tasse.', 116, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(463, 'Non considerare la deducibilità perché riguarda solo i ricchi.', 116, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(464, 'Versare solo cifre simboliche senza un piano, tanto l’importante è aderire.', 116, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(465, 'Versare almeno il minimo sindacale per ottenere l’intero contributo del datore di lavoro, che è denaro aggiuntivo.', 117, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(466, 'Non aderire al fondo pensione e rinunciare al contributo del datore per non vincolare soldi.', 117, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(467, 'Pensare che il contributo del datore vada restituito se si cambia lavoro.', 117, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(468, 'Ignorare i dettagli del contratto collettivo e non chiedere informazioni all’ufficio personale.', 117, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(469, 'Considerare l’aliquota agevolata (20% e poi a scalare) come un plus rispetto agli investimenti ordinari, specialmente su durate lunghe.', 118, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(470, 'Credere che i rendimenti del fondo pensione non siano tassati del tutto.', 118, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(471, 'Non interessarsi della differenza tra tassazione al 20% e 26% perché è poca cosa.', 118, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(472, 'Scegliere il fondo pensione solo in base alla tassazione, ignorando i costi di gestione.', 118, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(473, 'Inserire il risparmio dell’imposta di bollo nel calcolo del rendimento netto atteso del fondo pensione rispetto ad altri investimenti.', 119, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(474, 'Ignorare questo vantaggio perché l’imposta di bollo è minima.', 119, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(475, 'Pensare che il fondo pensione sia l’unico strumento esente da imposta di bollo.', 119, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(476, 'Non aprire un fondo pensione perché il risparmio di bollo non vale la perdita di liquidità.', 119, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(477, 'Versare solo la cifra che si è sicuri di non dover toccare prima della pensione, per non rischiare penali.', 120, 1, '2026-05-08 20:52:06', NULL, NULL, 1),
	(478, 'Mettere tutti i risparmi nel fondo pensione, tanto esistono le anticipazioni per ogni evenienza.', 120, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(479, 'Non versare nulla perché i vincoli sono una limitazione inaccettabile.', 120, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(480, 'Pensare che i soldi nel fondo pensione siano sempre liquidabili senza costi.', 120, 0, '2026-05-08 20:52:06', NULL, NULL, 1),
	(481, 'Trattarlo come un normale conto deposito da cui prelevare in qualsiasi momento.', 115, 0, '2026-05-08 23:28:08', '2026-05-08 23:28:08', 1, 1),
	(482, 'Considerarlo uno strumento previdenziale con vantaggi fiscali, ma con vincoli di liquidità fino alla pensione.', 115, 1, '2026-05-08 23:28:08', '2026-05-08 23:28:08', 1, 1),
	(483, 'Non aprirlo mai perché la pensione pubblica basterà sicuramente.', 115, 0, '2026-05-08 23:28:08', '2026-05-08 23:28:08', 1, 1),
	(484, 'Versarci tutti i risparmi, anche quelli che potrebbero servire a breve, per il vantaggio fiscale.', 115, 0, '2026-05-08 23:28:08', '2026-05-08 23:28:08', 1, 1);
