	('XMIL', 'Borsa Italiana', 'MI', 'IT', '09:30:00', '17:30:00', 'EUR', '2026-03-28 11:37:42', '2026-04-02 08:42:18', 1, 1);
INSERT INTO `explanations` (`id_explanation`, `id_lesson`, `body`, `created_at`, `last_update`, `id_user`, `active`) VALUES
	(1, 1, 'Immagina di dover affrontare una spesa importante tra tre anni. Se compri qualcosa solo perché ne parlano tutti, senza sapere se quei soldi potranno servirti prima, stai speculando, non investendo. L’app ti aiuterà a distinguere: fermati un attimo, chiediti quanto puoi vincolare e per quanto tempo. Solo dopo potrai decidere con calma. Blocca subito l’impulso di comprare per sentito dire; così eviterai di trasformare un piano sensato in una scommessa incontrollata.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(2, 2, 'Pensa al rischio come a una scadenza: non è il saliscendi giornaliero a fare danni, ma trovarsi senza soldi proprio quando ti servono. Se quei fondi devono restare investiti fino a una data precisa, sopporterai le oscillazioni. Se invece li ritiri prima, ogni piccolo calo diventa una perdita reale. L’app ti chiederà sempre: “Fino a quando puoi lasciarli lì?”. Solo dopo ti mostrerà gli strumenti adatti. Così eviti di vendere in preda al panico e di compromettere il tuo progetto.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(3, 3, 'Prima di inserire un ordine, l’app ti farà tre domande: a cosa servono questi soldi? Entro quando potresti averne bisogno? Quanto sarebbe grave non trovarli subito? È un filtro semplice ma potentissimo. Un prodotto pubblicizzato con insistenza può sembrare perfetto, ma se non risponde ai tuoi bisogni concreti, meglio passare oltre. La regola d’oro è: se non lo capisci fino in fondo, non comprarlo. Così eviti di ritrovarti con qualcosa che non fa per te.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(4, 4, 'Gestire il denaro non deve diventare un secondo lavoro. L’obiettivo è costruire una routine leggera: pochi strumenti, operazioni rare e un controllo mensile, non quotidiano. Se ti accorgi che stai dedicando troppo tempo a controllare quotazioni o a cambiare strategia, forse stai complicando le cose. L’app ti aiuterà a ricordare che la semplicità è una scelta di metodo. Meno azioni inutili, più serenità e, spesso, risultati migliori.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(5, 5, 'Guardare il valore del portafoglio tutti i giorni è come pesarsi ogni ora durante una dieta: ti stressa e non ti dà informazioni utili. Le oscillazioni di breve termine sono normali, ma rischiano di spaventarti e portarti a decisioni affrettate. L’app ti suggerirà di impostare un controllo mensile, o trimestrale, a seconda del tuo orizzonte. Solo così potrai valutare davvero se stai rispettando il tuo piano, senza lasciarti condizionare dall’umore del momento.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(6, 6, 'Hai presente quando entri in un negozio senza sapere cosa ti serve? Rischi di uscire con qualcosa di inutile. Con gli investimenti è lo stesso: se parti dal prodotto (un fondo, un’azione, una polizza) senza aver chiarito il tuo bisogno, finisci per comprare qualcosa che non risponde ai tuoi obiettivi reali. L’app ti guiderà a invertire l’ordine: prima scrivi a cosa serve il denaro e la data stimata, poi cerchi lo strumento adatto. Così ogni scelta sarà coerente con la tua vita.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(7, 7, 'Una decisione informata non richiede di diventare esperti, ma di avere le informazioni essenziali: quanto, quando e con quale margine di oscillazione. L’app ti mostrerà queste tre variabili per ogni scelta. Se una proposta è troppo complicata o non riesci a spiegartela in due frasi, probabilmente non fa per te. Prenditi il tempo di capire: un clic impulsivo può costare più di una piccola attesa.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(8, 8, 'Le scorciatoie in finanza sono come le diete miracolose: promettono risultati veloci e senza fatica, ma quasi sempre deludono. Prodotti che garantiscono rendimenti alti e zero rischi, consigli spacciati per “affari imperdibili”, strategie copiate da sconosciuti: sono tutte trappole. L’app ti ricorderà che costruire un patrimonio richiede metodo, non trucchi. Se sembra troppo bello per essere vero, fermati e torna alle basi.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(9, 9, 'L’autonomia finanziaria significa saper prendere decisioni da soli, senza dipendere da consigli di cui non capisci le motivazioni. Non è rifiutare ogni aiuto, ma essere in grado di valutare se un suggerimento è coerente con i tuoi obiettivi. L’app ti aiuterà a costruire questa capacità con passi graduali: imparerai a leggere le schede prodotto, a calcolare il rendimento netto e a riconoscere i conflitti d’interesse. Così sarai tu a decidere, con consapevolezza.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(10, 10, 'Il metodo semplice non è una banalità: è l’arte di concentrarsi su ciò che conta davvero. Obiettivi chiari, pochi strumenti ben scelti, controlli periodici e niente operazioni inutili. L’app ti proporrà un percorso lineare, senza fronzoli. Se seguirai questi principi, ridurrai l’ansia e aumenterai la probabilità di raggiungere i tuoi traguardi. Ricorda: la complicazione è spesso nemica dei buoni risultati.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(11, 17, 'Il conto corrente è il tuo portafoglio digitale: deve contenere solo ciò che ti serve per le spese dei prossimi 30-60 giorni, non i risparmi di una vita. Se lo tieni troppo pieno, i soldi si svalutano e paghi imposte di bollo inutilmente; se lo svuoti per investire tutto, rischi di trovarti in difficoltà per le spese quotidiane. L’app ti aiuterà a separare la liquidità dal resto, così avrai sempre la cifra giusta a portata di mano.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(12, 18, 'Un’emergenza reale è la rottura improvvisa dell’auto che usi per lavorare, non la prossima vacanza low-cost. Il fondo di emergenza serve a coprire quelle spese inattese che ti costringerebbero a chiedere prestiti o a vendere investimenti in perdita. Devi tenerlo in strumenti molto liquidi e sicuri, anche se rendono poco: la sua funzione non è guadagnare, ma esserci quando serve. L’app ti guiderà a definire l’ammontare giusto in base alle tue spese mensili e alla tua stabilità lavorativa.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(13, 19, 'Ci sono spese che non sono urgenti ora, ma arriveranno tra qualche anno: la sostituzione dell’auto, la ristrutturazione di casa, un master. Per questi obiettivi conta la scadenza, non il rendimento stellare. Inserendoli nel terzo pilastro, potrai destinare a ciascuno uno strumento con scadenza vicina alla data del bisogno. Così eviti di mettere quei soldi sull’azionario e scoprire, proprio quando ti servono, che il mercato è sceso del 20%.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(14, 20, 'Il quarto pilastro è il motore della crescita: qui metterai i soldi che non ti servono per almeno dieci anni, e per questo puoi sopportare oscillazioni anche ampie. L’orizzonte lungo ti permette di puntare sull’azionario globale con ETF diversificati, senza preoccuparti delle turbolenze di breve periodo. L’app ti aiuterà a capire quanta parte del tuo patrimonio può realisticamente restare investita per un decennio o più, separandola nettamente dalle somme che ti servono prima.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(15, 21, 'Visualizza il tuo patrimonio come una piramide: alla base la liquidità per le spese correnti, subito sopra il fondo di emergenza, poi gli obiettivi a medio termine e infine, in cima, il lungo termine. Non puoi costruire la punta se la base è debole. Se salti i primi gradini, rischi di dover smantellare gli investimenti azionari proprio nel momento peggiore. L’app ti mostrerà questa piramide con i tuoi numeri, così capirai subito se hai trascurato qualche livello.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(16, 22, 'Tempo e rischio sono legati a doppio filo: più tempo hai a disposizione, più puoi permetterti strumenti che oscillano molto, perché le fasi negative vengono assorbite dalle fasi positive. Al contrario, se l’orizzonte è breve, devi ridurre il rischio per evitare di trovarti in perdita proprio quando devi spendere. L’app ti farà inserire per ogni obiettivo una data stimata e ti suggerirà automaticamente il livello di rischio adatto.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(17, 23, 'Uno degli errori più comuni è vedere il conto corrente che non rende e pensare: “Investo tutto, tanto mi serviranno fra un po’”. Ma le spese correnti e gli imprevisti non aspettano: se quei soldi non sono subito disponibili, rischi di dover vendere in fretta strumenti volatili, magari in perdita. L’app ti ricorderà sempre di lasciare la liquidità necessaria prima di destinare il resto agli investimenti. Così proteggi la tua tranquillità quotidiana.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(18, 24, 'Ogni euro che possiedi ha un compito preciso, anche se ancora non lo hai definito. Alcuni euro servono per la spesa di domani, altri per l’emergenza, altri per la pensione. Se non assegni una funzione, finisci per usare i soldi in modo disordinato: magari investi a lungo termine ciò che ti serve tra un anno, oppure tieni inutilmente liquidi i risparmi per la pensione. L’app ti aiuterà a dare un ruolo a ogni parte del tuo patrimonio, per poi scegliere gli strumenti giusti.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(19, 25, 'Pensare subito al rendimento senza aver messo al sicuro le basi è come preoccuparsi del design del tetto mentre le fondamenta sono fragili. Prima devi assicurarti di avere liquidità per le spese correnti e un cuscinetto per le emergenze. Solo dopo puoi cercare rendimenti più alti per gli obiettivi di lungo termine. L’app ti farà costruire il tuo piano in questo ordine, bloccando le scelte troppo rischiose finché le coperture essenziali non sono al loro posto.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(20, 26, 'L’orizzonte temporale è la bussola di ogni investimento. Non è quanto vorresti tenerli, ma quanto realisticamente puoi farne a meno. Se tra un anno ti serve per comprare casa, l’orizzonte è un anno, non dieci. Sbagliare questa stima ti porta a usare strumenti inadeguati e a prendere decisioni affrettate quando il mercato scende. Inserisci sempre la data esatta in cui prevedi di aver bisogno di quei fondi: l’app userà quel dato per guidarti.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(21, 33, 'Il conto corrente principale è il centro operativo: da qui partono bollette, affitto, spesa. Deve essere comodo, economico e contenere solo la liquidità necessaria per il mese più un piccolo margine. Se ci tieni cifre elevate, paghi l’imposta di bollo e perdi potere d’acquisto. Se lo svuoti, rischi di andare in rosso. L’app ti aiuterà a capire qual è la giacenza media ideale e a spostare il resto verso conti deposito o investimenti.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(22, 34, 'Non tutti i conti sono uguali: canone mensile, imposta di bollo, commissioni sui bonifici, costi per prelievi. A fine anno possono pesare più del previsto. L’app ti inviterà a confrontare le condizioni del tuo conto attuale con quelle di altri istituti, soprattutto conti online a costo zero. Scegliere il conto giusto è uno dei modi più semplici per ridurre le spese fisse senza rinunciare a nulla.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(23, 35, 'Oggi molte banche online offrono conti a zero spese con la stessa operatività di una filiale fisica. Se hai familiarità con lo smartphone e non hai bisogno di consulenza in sede, un conto online può farti risparmiare decine di euro all’anno. L’app ti mostrerà pro e contro di entrambe le soluzioni, così potrai decidere in base alle tue abitudini, non alla pubblicità.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(24, 36, 'Avere un secondo conto può essere utile per separare le spese fisse da quelle variabili, oppure per gestire un’attività. Ma attenzione: ogni conto aggiuntivo comporta costi e imposte di bollo separate. L’app ti aiuterà a valutare se ti serve davvero o se puoi organizzarti diversamente, ad esempio usando un conto deposito per la riserva di liquidità.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(25, 37, 'Le carte conto sono un ibrido: funzionano come un conto con IBAN ma spesso hanno costi diversi e limiti operativi. Possono essere comode per piccole spese, ma non sono conti correnti completi. L’app ti spiegherà le differenze e ti aiuterà a capire se possono sostituire il conto tradizionale o se è meglio tenerle come soluzione complementare.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(26, 38, 'Domiciliare le bollette e le rate fisse è comodo: non rischi dimenticanze e spesso risparmi sulle commissioni. Però devi assicurarti che sul conto ci sia sempre copertura sufficiente, altrimenti scattano penali. L’app può aiutarti a tenere traccia degli addebiti automatici e a programmare la giacenza minima per coprirli, così da evitare sorprese.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(27, 39, 'Alcuni conti impongono limiti o commissioni su prelievi e bonifici dopo una certa soglia. Se prelevi spesso o devi trasferire somme consistenti, confronta le condizioni: un bonifico istantaneo può costare caro. L’app ti suggerirà di pianificare le operazioni più grosse con bonifici ordinari gratuiti e di usare conti che non penalizzino il tuo stile di utilizzo.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(28, 40, 'L’imposta di bollo si applica quando la giacenza media supera i 5.000 euro. Se tieni abitualmente più di quella cifra sul conto, paghi 34,20 euro all’anno. Non è una cifra enorme, ma è un costo evitabile. L’app ti avviserà se la tua liquidità è eccessiva e ti consiglierà di spostare il surplus su un conto deposito o su strumenti a breve termine.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(29, 41, 'Cambiare banca oggi è più semplice di quanto pensi: puoi trasferire il conto corrente senza costi e senza perdere gli addebiti automatici. Se il tuo conto attuale è costoso o poco pratico, valuta il passaggio a un operatore più moderno. L’app ti guiderà nei passaggi principali, dalla scelta del nuovo conto alla comunicazione al vecchio istituto.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(30, 42, 'Oltre ai costi, conta l’esperienza d’uso: un’app intuitiva, l’assistenza clienti rapida, la possibilità di operare 24 ore su 24. La comodità ti fa risparmiare tempo e riduce lo stress. Quando scegli un conto, non guardare solo il prezzo: leggi le recensioni e prova l’interfaccia. L’app ti aiuterà a individuare i parametri che contano per te.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(31, 49, 'La carta di debito preleva i soldi direttamente dal tuo conto al momento del pagamento. Non puoi spendere più di quanto hai depositato, il che la rende ideale per le spese quotidiane e per tenere sotto controllo il budget. Se la usi all’estero, controlla eventuali commissioni sul cambio valuta. L’app ti aiuterà a scegliere la carta di debito più adatta alle tue abitudini, confrontando costi e funzionalità.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(32, 50, 'Con la carta di credito paghi oggi e saldi il conto il mese successivo. Può essere utile per noleggiare un’auto, prenotare un hotel o gestire spese impreviste, ma attenzione: se non ripaghi l’intero saldo, scattano interessi elevati. Non va mai considerata come un’estensione del reddito. L’app ti mostrerà il massimale, il tasso applicato e ti aiuterà a mantenere il saldo sempre sotto controllo.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(33, 51, 'Una carta ricaricabile non è collegata a un conto corrente: la carichi quando vuoi e spendi solo quanto hai inserito. È comoda per separare le spese personali o per dare una paghetta ai figli, ma spesso ha costi di ricarica e limiti di utilizzo giornalieri. L’app ti aiuterà a capire quando conviene e quando invece è solo una spesa in più.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(34, 52, 'Il massimale della carta di credito non è un bonus, è il tetto massimo che puoi spendere questo mese e che dovrai ripagare entro la scadenza. Superarlo o usarlo tutto pensando di spalmare il rimborso su più mesi è l’inizio di una spirale pericolosa. L’app ti inviterà a impostare un limite personale inferiore al massimale, per restare sempre in una zona di sicurezza.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(35, 53, 'Le carte di credito classiche non danno interessi a tuo favore, anzi: se non saldi il conto, ti applicano interessi passivi altissimi, spesso sopra il 15%. Alcune carte conto offrono un minimo rendimento sulla giacenza, ma è trascurabile. Non scegliere una carta pensando di guadagnarci: usala come strumento di pagamento, non di investimento. L’app ti farà simulare il costo reale di un pagamento rateale, per farti capire quanto pagheresti di interessi.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(36, 54, 'Molte carte di credito hanno un canone annuo. Prima di attivarla, verifica se i servizi inclusi (assicurazioni viaggio, cashback) valgono più del costo. Se viaggi poco o non usi quei benefit, una carta senza canone può essere la scelta migliore. L’app ti guiderà in un confronto rapido: costo annuo meno valore reale dei servizi extra. Così deciderai con i numeri, non con la pubblicità.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(37, 55, 'Prelevare contanti con la carta di credito è quasi sempre un’operazione da evitare: commissioni elevate, interessi immediati e nessun periodo di grazia. È un prestito travestito da prelievo. L’app ti avviserà con un messaggio chiaro quando stai per usare questa funzione, suggerendoti alternative come l’uso del fondo di emergenza o un piccolo bonifico dal conto deposito.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(38, 56, 'Quando paghi in dollari o sterline, la tua banca applica un tasso di cambio e spesso una commissione aggiuntiva (dall’1% al 3%). Alla fine il costo finale può essere più alto del previsto. Se viaggi spesso, esistono carte con conversioni a tasso interbancario e zero commissioni. L’app ti aiuterà a individuare la soluzione migliore per il tuo profilo di spesa internazionale.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(39, 57, 'Per chi viaggia spesso, esistono carte che offrono coperture assicurative, accesso alle lounge e miglia aeree. Tuttavia, il canone può essere alto. Prima di sottoscriverla, calcola quante volte all’anno utilizzerai quei servizi: se non copri il costo con i benefit, meglio una carta senza fronzoli. L’app ti aiuterà a fare un bilancio costi-benefici personalizzato.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(40, 58, 'Il credito, se usato male, diventa una catena. La regola d’oro è: paga sempre il saldo completo a fine mese, e se non puoi farlo, fermati subito. L’app ti invierà un alert quando il rapporto tra saldo e massimale supera una certa soglia, così potrai correggere la rotta prima di finire in difficoltà.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(41, 65, 'Il conto titoli è il contenitore dove comprerai ETF, obbligazioni e altri strumenti. È separato dal conto corrente, anche se spesso vengono aperti insieme. La sua scelta determina quali mercati puoi raggiungere, le commissioni che pagherai e il regime fiscale. Non serve il broker più famoso o quello con l’app più accattivante: serve quello che si adatta ai tuoi strumenti e al tuo modo di investire. L’app ti aiuterà a identificare i parametri fondamentali e a fare un confronto semplice.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(42, 66, 'Non tutti i conti titoli permettono di acquistare su tutte le borse. Se il tuo piano prevede solo ETF quotati su Borsa Italiana, un intermediario italiano in regime amministrato è più che sufficiente. Se invece ti servono mercati esteri, verifica che siano accessibili e a quali costi. Aprirne uno complicato solo perché “offre di più” può diventare un impiccio. L’app ti mostrerà quali mercati ti servono davvero in base agli strumenti che hai scelto.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(43, 67, 'Ogni operazione ha un costo: alcuni broker applicano una commissione fissa in euro, indipendentemente dall’importo. Se fai pochi acquisti all’anno ma di importo consistente, questa tariffa può essere conveniente. Se invece investi piccole somme ogni mese, una commissione fissa di 5-8 euro può erodere una fetta importante del tuo capitale. L’app ti aiuterà a calcolare l’incidenza delle commissioni sul tuo stile di accumulo.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(44, 68, 'Alcuni intermediari applicano una commissione percentuale sul controvalore dell’ordine, ad esempio lo 0,19%. Per ordini piccoli può essere più economica di una commissione fissa, ma su importi elevati lievita. Devi conoscere la tua operatività tipica: quanto investi a ogni esecuzione? L’app incrocerà i tuoi importi con i piani commissionali per suggerirti la soluzione più efficiente.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(45, 69, 'Avere il conto titoli separato dal conto corrente principale ti aiuta a tenere sotto controllo la parte investita ed evitare di confondere la liquidità con il portafoglio. Inoltre, se vuoi cambiare banca, puoi trasferire il conto titoli senza dover spostare anche il conto corrente. L’app ti consiglierà di mantenere questa separazione per chiarezza mentale e operativa.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(46, 70, 'Trasferire i titoli da un intermediario all’altro è un diritto e non comporta la vendita degli strumenti, quindi niente tasse. Ma ci possono volere alcune settimane e a volte ci sono costi fissi. L’app ti spiegherà come avviare la procedura senza intoppi e quando conviene farlo, ad esempio se trovi un broker più economico o con regime fiscale più adatto a te.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(47, 71, 'Avere due conti titoli può avere senso per separare diverse strategie, ma complica la gestione e aumenta la possibilità di errori. Se non hai un motivo valido (ad esempio, un conto per il lungo termine e uno per il fondo pensione), meglio restare su un unico intermediario affidabile. L’app ti aiuterà a valutare se il gioco vale la candela.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(48, 72, 'I broker esteri possono avere commissioni bassissime, ma spesso ti lasciano in regime dichiarativo: dovrai compilare il quadro RW e calcolare le tasse da solo o con un commercialista. Non sempre il risparmio sulle commissioni copre il costo della consulenza fiscale. L’app ti mostrerà un confronto realistico, includendo anche il valore del tuo tempo e della semplicità.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(49, 73, 'Le app di trading spingono a operare spesso con interfacce colorate e notifiche push. Questo è l’opposto di ciò che serve a un investitore di lungo termine: meno operazioni fai, meglio è. Se scegli una banca che offre sia conto titoli sia un’app semplice, disattiva gli alert e imposta un promemoria mensile. L’app ti aiuterà a resistere alla tentazione di “fare qualcosa”.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(50, 74, 'Il regime amministrato significa che l’intermediario fa da sostituto d’imposta: paga le tasse al posto tuo e tu non devi dichiarare nulla. Quello dichiarativo ti obbliga a inserire ogni anno plusvalenze e minusvalenze nella dichiarazione dei redditi. Per la maggior parte degli investitori, il regime amministrato è la scelta più semplice e sicura. L’app ti aiuterà a capire subito in quale regime opera il tuo conto titoli.', '2026-05-08 20:52:03', NULL, NULL, 1),
	(51, 81, 'Immagina due investimenti: uno ti fa guadagnare 500 euro in tre anni, l’altro 500 euro in sei mesi. Quale preferisci? Se guardi solo il guadagno assoluto, non capisci la differenza. Devi sempre trasformarlo in rendimento percentuale su base annua. L’app ti mostrerà il dato in due formati: guadagno in euro e rendimento annualizzato. Così potrai confrontare mele con mele.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(52, 82, 'Capitale è ciò che investi all’inizio. Montante è ciò che ottieni alla fine, maggiorato degli interessi o dei rendimenti. Se investi 10.000 euro e dopo cinque anni hai 12.000 euro, il montante è 12.000. La differenza non è solo il guadagno: devi capire a quale tasso percentuale annuo corrisponde. L’app ti farà familiarizzare con queste parole, in modo che quando leggi un prospetto informativo tu sappia esattamente di cosa parla.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(53, 83, 'L’interesse composto è il tuo migliore amico se hai tempo. Significa che gli interessi guadagnati generano a loro volta interessi. Un esempio: 1.000 euro al 5% annuo dopo un anno diventano 1.050; l’anno dopo il 5% si calcola su 1.050, non su 1.000. In 20 anni la differenza rispetto all’interesse semplice è enorme. L’app ti mostrerà la crescita del tuo capitale con una simulazione interattiva, facendoti toccare con mano l’effetto moltiplicatore del tempo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(54, 84, 'Due prodotti che hanno prodotto lo stesso rendimento totale in periodi diversi non sono uguali. Uno può aver reso il 10% in 5 anni, l’altro il 10% in 2 anni. Per confrontarli devi annualizzare: trasformare il rendimento nel tasso medio annuo equivalente. L’app ti offrirà una calcolatrice semplice per farlo in automatico, inserendo solo importo iniziale, finale e durata.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(55, 85, 'Annualizzare significa rispondere alla domanda: “Quale tasso di interesse annuo costante avrebbe prodotto questo risultato?”. La formula non è semplicemente dividere il rendimento totale per gli anni, perché l’interesse composto fa curvare la crescita. L’app applicherà la formula corretta e ti mostrerà il tasso annuo composto (CAGR), che è il parametro standard per confrontare investimenti di durata diversa.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(56, 86, 'Ogni investimento può generare flussi positivi (cedole, dividendi) e negativi (il costo di acquisto iniziale). Per valutarlo correttamente, devi considerare quando entrano ed escono i soldi. Un’obbligazione che paga cedole annuali non è uguale a una che le paga tutte alla fine. L’app ti farà vedere un diagramma temporale dei flussi, così capirai subito la distribuzione nel tempo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(57, 87, 'Le cedole sono pagamenti periodici che ricevi da un’obbligazione; i dividendi sono la parte di utile che una società distribuisce agli azionisti. In entrambi i casi, quei flussi sono già tassati e, se non li reinvesti, non generano interesse composto. L’app ti mostrerà l’impatto dei flussi distribuiti rispetto a quelli accumulati, aiutandoti a scegliere tra strumenti a distribuzione o ad accumulo in base ai tuoi bisogni.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(58, 88, 'Il TIR (tasso interno di rendimento) è quel tasso che rende uguale il valore attuale dei flussi futuri al prezzo pagato oggi. In parole povere: è il rendimento medio annuo che ti aspetti da un investimento con flussi variabili. L’app lo calcolerà per te quando inserisci acquisti di obbligazioni o altri strumenti con cedole, mostrandoti un numero facile da confrontare con altri investimenti.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(59, 89, 'Il rendimento che vedi pubblicizzato è quasi sempre lordo. Devi togliere le tasse (di solito il 26% su plusvalenze e cedole) e i costi di transazione. Solo così ottieni il netto, che è ciò che finisce davvero in tasca tua. L’app ti mostrerà entrambi i numeri, ma metterà in evidenza quello netto, perché è l’unico che conta per la tua pianificazione.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(60, 90, 'Un euro oggi vale più di un euro domani, perché puoi investirlo e farlo fruttare. Questo principio, detto “valore temporale del denaro”, è alla base di tutta la finanza. L’app ti farà ragionare in termini di potere d’acquisto futuro: quando pianifichi una spesa tra dieci anni, devi considerare che quei soldi dovranno essere rivalutati per mantenere lo stesso valore reale.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(61, 97, 'Una vera emergenza è un evento urgente, imprevisto e necessario: la caldaia che si rompe a gennaio, una riparazione urgente all’auto, una spesa dentista non rinviabile. Non è la vacanza last minute né il telefono nuovo in offerta. Distinguere è fondamentale per non prosciugare il fondo per spese prevedibili o voluttuarie. L’app ti farà domande filtro prima di permetterti di attingere al fondo, aiutandoti a mantenere la disciplina.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(62, 98, 'Quanto mettere nel fondo? Dipende dalle tue spese mensili, dalla stabilità del lavoro e dalla composizione familiare. In genere si consiglia da 3 a 6 mesi di spese essenziali, ma per un lavoratore autonomo può servire un anno. L’app ti guiderà a calcolare l’importo giusto per te, inserendo le tue spese medie e il tuo profilo di rischio personale.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(63, 99, 'Una piccola parte del fondo di emergenza può stare sul conto corrente per le urgenze immediate, ma non tutta: rischi di spenderla per altri motivi e di pagare l’imposta di bollo sulla giacenza. Tieni sul conto solo il necessario per coprire un paio di settimane di imprevisti; il resto mettilo in strumenti liquidi ma separati. L’app ti mostrerà come suddividere il fondo tra conto e altri strumenti.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(64, 100, 'Il conto deposito è uno degli strumenti più adatti per il fondo di emergenza: è sicuro, liquido (se svincolabile) e offre un piccolo rendimento. Non è un investimento per arricchirsi, ma un parcheggio protetto. L’app ti aiuterà a confrontare le offerte di diversi conti deposito, verificando svincolo, tassi e costi.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(65, 101, 'Un deposito svincolabile ti permette di recuperare i soldi quando vuoi, rinunciando in tutto o in parte agli interessi già maturati. Per il fondo di emergenza è essenziale: se vincoli i soldi e poi non puoi toccarli, il fondo non serve. L’app ti segnalerà sempre se un prodotto è svincolabile e a quali condizioni, perché la liquidità è il primo requisito.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(66, 102, 'I BOT (Buoni Ordinari del Tesoro) e i BTP a breve scadenza possono integrare il fondo di emergenza. Rendono qualcosa in più del conto deposito e sono negoziabili, ma attenzione: se li vendi prima della scadenza, il prezzo può oscillare, anche se di poco. L’app ti aiuterà a scegliere titoli con scadenze molto ravvicinate e a calcolare il rendimento netto al momento dell’acquisto.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(67, 103, 'Gli ETF monetari replicano un tasso a breve termine (ad esempio il €STR) e oscillano pochissimo. Sono un’alternativa moderna al conto deposito, ma devi avere un conto titoli e pagare le commissioni di acquisto. L’app ti mostrerà un confronto tra ETF monetari e conti deposito, calcolando il rendimento netto al netto di tasse e costi.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(68, 104, 'Un’emergenza richiede tempi rapidi: se per riavere i tuoi soldi devi aspettare 15 giorni o vendere strumenti complicati, il fondo non sta funzionando. Il criterio chiave è la velocità di smobilizzo. L’app ti farà verificare, per ogni strumento in cui hai allocato il fondo, quanti giorni servono per trasformarlo in denaro contante sul tuo conto corrente.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(69, 105, 'Il fondo di emergenza non deve mai essere investito in azioni, ETF tematici o obbligazioni lunghe: quando ti servono, quei soldi potrebbero valere molto meno. La sicurezza del capitale è prioritaria rispetto al rendimento. L’app bloccherà qualsiasi tentativo di destinare il fondo a strumenti volatili, ricordandoti la sua funzione primaria.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(70, 106, 'Se vivi in coppia o hai figli, il fondo di emergenza va dimensionato su tutta la famiglia. Le spese improvvisi possono riguardare chiunque nel nucleo. Inoltre, è bene che entrambi i partner sappiano come accedere rapidamente a quei fondi. L’app ti permetterà di condividere in modo sicuro le istruzioni operative con il tuo partner, senza rivelare l’intero patrimonio.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(71, 113, 'Hai in mente una spesa importante tra 2-5 anni? Potrebbe essere l’anticipo per una casa, un master universitario o la sostituzione dell’auto. Questi obiettivi vanno gestiti con strumenti a scadenza, come obbligazioni singole, così sai esattamente quando riavrai il capitale. L’app ti chiederà la data esatta e ti mostrerà solo strumenti con scadenza compatibile, bloccando quelli più rischiosi.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(72, 114, 'Le spese prevedibili non sono emergenze: sai già che arriveranno. La differenza è che puoi pianificarle con calma. L’errore più grave è mettere quei soldi in azioni, attirati dal rendimento potenziale, per poi trovarsi con un calo del 20% proprio quando devi pagare. L’app ti ricorderà sempre di abbinare ogni spesa certa a uno strumento certo, non a un’oscillazione.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(73, 115, 'Quando compri un’obbligazione, la scadenza è il momento in cui l’emittente ti rimborsa il valore nominale. Deve coincidere con la data in cui prevedi di spendere quei soldi. Se la scadenza è troppo lunga, potresti dover vendere prima a prezzi incerti; se è troppo breve, dovrai reinvestire più volte. L’app ti aiuterà a fare il match esatto tra la data del tuo obiettivo e la scadenza del titolo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(74, 116, 'Un’obbligazione è un prestito che fai all’emittente (Stato o azienda). Lui si impegna a pagarti cedole periodiche e a restituirti il capitale alla scadenza. Più l’emittente è rischioso, più alte saranno le cedole, ma anche la probabilità che non venga rimborsato. L’app ti mostrerà sempre il rating e la probabilità di default stimata, così potrai giudicare se il rischio è adatto a te.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(75, 117, 'Le cedole sono come gli interessi sul prestito che hai concesso. Possono essere fisse o variabili, annuali o semestrali. Ma attenzione: una cedola alta non sempre significa un buon affare; se il prezzo dell’obbligazione è sopra 100, il rendimento effettivo a scadenza sarà inferiore. L’app ti calcolerà sempre il rendimento netto a scadenza, non ti farà abbagliare dalla sola cedola.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(76, 118, 'Alla scadenza, l’emittente ti rimborsa il valore nominale dell’obbligazione, di solito 100 euro per ogni unità. Se l’hai pagata meno di 100, avrai un guadagno aggiuntivo oltre alle cedole; se l’hai pagata più di 100, subirai una minusvalenza parziale. L’app ti mostrerà chiaramente questi due componenti, così potrai valutare il rendimento complessivo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(77, 119, 'Come già visto, il rendimento lordo non tiene conto delle tasse. Su obbligazioni governative italiane la tassazione è agevolata al 12,5%; su quelle corporate è 26%. La differenza sul netto può essere rilevante. L’app applicherà automaticamente l’aliquota corretta e ti mostrerà il rendimento netto a scadenza, l’unico che dovrebbe guidare la tua scelta.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(78, 120, 'Un “ladder” è una scala: compri più obbligazioni con scadenze diverse, ad esempio a 1, 2, 3 anni. Quando la prima scade, reinvesti il capitale in una nuova obbligazione a 3 anni. Questo ti dà liquidità periodica e riduce il rischio di repentini cambi di tassi. L’app ti permetterà di costruire e visualizzare la tua scala, gestendo facilmente i reinvestimenti.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(79, 121, 'La durata finanziaria (duration) misura la sensibilità del prezzo dell’obbligazione ai tassi. Non serve conoscerla in dettaglio, ma il principio è: più lunga è la scadenza, più il prezzo oscilla se i tassi variano. Per obiettivi brevi, meglio duration bassa. L’app ti segnalerà se stai scegliendo un titolo con duration troppo alta rispetto alla tua data di spesa, per evitare brutte sorprese.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(80, 122, 'Le azioni sono per il lungo termine (minimo 10 anni). Se devi spendere i soldi tra tre anni, anche un ETF azionario globale può perdere il 30% in quel lasso di tempo. È successo in passato e può succedere ancora. L’app ti impedirà di assegnare obiettivi a medio termine all’azionario, mostrandoti il massimo ribasso storico per la durata che hai indicato.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(81, 129, 'Il prezzo di un’obbligazione può essere sopra o sotto 100. Se è sopra 100, significa che il tasso cedolare è più alto dei tassi di mercato attuali: paghi di più, ma ricevi cedole più generose. Se è sotto 100, acquisti a sconto, ma le cedole sono basse. Non guardare solo il prezzo o solo la cedola: conta il rendimento complessivo. L’app ti mostrerà un grafico che lega prezzo, cedola e rendimento effettivo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(82, 130, 'Immagina due obbligazioni: una paga cedola 5% e costa 110, l’altra paga cedola 2% e costa 98. Quale conviene? Devi calcolare il rendimento a scadenza, che include sia le cedole sia il guadagno/perdita in conto capitale. Spesso la cedola più bassa dà un rendimento migliore. L’app farà il calcolo per te, così non cadrai nella trappola di guardare solo la cedola.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(83, 131, 'I titoli di Stato (BOT, BTP, CCT) sono emessi dallo Stato italiano per finanziare il debito pubblico. Sono considerati relativamente sicuri, ma non privi di rischio: se l’Italia avesse difficoltà, il loro prezzo scenderebbe. Per il terzo pilastro sono spesso adatti, specialmente quelli a breve-medio termine. L’app ti aiuterà a scegliere la giusta tipologia in base al tuo obiettivo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(84, 132, 'Le obbligazioni corporate sono emesse da aziende. Rendono più dei titoli di Stato, ma comportano il rischio che l’azienda fallisca. Non c’è nulla di male a inserirne una piccola quota, ma vanno scelte con attenzione, diversificando. L’app ti mostrerà il rating, il settore e il paese dell’emittente, aiutandoti a non concentrare troppo il rischio.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(85, 133, 'Il rischio emittente è la probabilità che chi ha preso in prestito i tuoi soldi non li restituisca alla scadenza. Si misura con il rating (AAA la massima sicurezza, sotto BBB- è speculativo). Nel terzo pilastro, meglio stare su emittenti con rating medio-alto. L’app ti colorerà di verde, giallo o rosso ogni obbligazione in base al rating, per una scelta immediata.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(86, 134, 'Quando compri un’obbligazione tra due date di cedola, devi pagare al venditore il rateo, cioè la parte di cedola già maturata ma non ancora incassata. Poi tu incasserai l’intera cedola, ma il tuo guadagno netto sarà la differenza. L’app calcolerà automaticamente il rateo e te lo mostrerà come parte del prezzo di acquisto, così non avrai sorprese.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(87, 135, 'Comprare obbligazioni in dollari o sterline aggiunge il rischio di cambio: se la valuta estera si deprezza rispetto all’euro, il tuo rendimento si riduce o diventa negativo. Per il terzo pilastro, meglio evitare questo doppio rischio e restare su strumenti in euro. L’app ti avviserà con un segnale se stai per acquistare un titolo in valuta diversa.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(88, 136, 'Le obbligazioni si comprano sul mercato secondario (Borsa Italiana o altre piattaforme). I prezzi variano in base a domanda e offerta, non sono fissi. Puoi comprare sia in fase di emissione (asta) sia sul mercato secondario. L’app ti spiegherà come partecipare alle aste per i titoli di Stato e come inserire un ordine sul mercato secondario con le giuste cautele.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(89, 137, 'Quando inserisci un ordine per un’obbligazione, devi scegliere tra prezzo limitato (imponi un tetto massimo) o “al meglio” (esegui subito qualunque sia il prezzo). Per obbligazioni poco liquide, l’ordine al meglio può essere rischioso. L’app ti guiderà verso l’ordine limitato e ti mostrerà il book per capire il giusto prezzo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(90, 138, 'Più la scadenza è lontana, più il prezzo dell’obbligazione oscillerà al variare dei tassi di interesse. Se devi vendere prima della scadenza, potresti trovarti in perdita anche se l’emittente è solidissimo. Per questo è cruciale allineare scadenza e orizzonte temporale. L’app ti mostrerà un grafico della “curva dei rendimenti” per confrontare diverse scadenze.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(91, 145, 'Non tutti i consigli sono gratuiti o disinteressati. Alcuni promotori guadagnano commissioni sui prodotti che ti propongono. Un buon consiglio parte dai tuoi obiettivi, non dal prodotto. L’app ti aiuterà a riconoscere i segnali di conflitto d’interesse: proposte troppo insistenti, costi nascosti, prodotti complessi di cui non capisci il funzionamento. Impara a chiedere sempre: “Quanto guadagna lei se compro questo?”.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(92, 146, '“Capitale garantito” è una delle frasi più abusate. Spesso la garanzia riguarda solo il capitale investito inizialmente e solo a scadenza, dopo molti anni, con costi altissimi che erodono qualsiasi rendimento. In pratica, potresti ritrovarti con gli stessi soldi di partenza, ma svalutati dall’inflazione. L’app ti mostrerà il rendimento reale stimato al netto di costi e inflazione, smascherando le false garanzie.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(93, 147, 'Le polizze finanziarie (ramo I, multiramo) spesso mescolano assicurazione e investimento in un prodotto unico, con costi elevati e vincoli di uscita. Raramente sono la soluzione migliore per investire. Di solito conviene separare: una polizza assicurativa pura per i rischi, e strumenti di investimento semplici per il capitale. L’app ti metterà in guardia mostrandoti il costo percentuale annuo di queste polizze rispetto a un ETF equivalente.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(94, 148, 'Crowdfunding immobiliare, vini, orologi, cripto-attività: sono tutti investimenti complessi, spesso illiquidi e con rischi elevati. Possono anche andare bene, ma non sono adatti a chi sta costruendo le basi. L’app ti suggerirà di limitarli a una piccolissima percentuale del patrimonio (0-5%) solo dopo aver completato i quattro pilastri. Prima di tutto, la solidità.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(95, 149, 'Un prodotto complesso è come un cibo con un’etichetta lunghissima: se non capisci cosa contiene, non metterlo nel piatto. Strumenti derivati, certificates, obbligazioni strutturate: spesso nascondono costi e rischi. L’app ti aiuterà a identificarli con una semplice domanda: “So spiegare esattamente come funziona e quanto mi costerà?”. Se la risposta è no, meglio passar oltre.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(96, 150, 'Vedere il portafoglio in rosso fa male, ma vendere subito trasforma una perdita temporanea in una definitiva. Se l’orizzonte è lungo e lo strumento è valido, spesso conviene aspettare. L’app ti mostrerà, quando tenti di vendere in perdita, un grafico storico del recupero dopo un crollo, per aiutarti a resistere all’impulso emotivo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(97, 151, 'Nessuno sa cosa farà il mercato domani: nemmeno gli esperti in TV. Cercare di indovinare il momento giusto per entrare o uscire è una strategia che fallisce nella maggior parte dei casi. L’approccio vincente è entrare con un piano e restare investiti. L’app ti ricorderà quante volte chi ha provato a prevedere ha perso i giorni migliori di rimbalzo, con una piccola simulazione.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(98, 152, 'Ogni operazione costa: commissioni, spread, tasse. Inoltre, più muovi il portafoglio, più sei esposto a errori emotivi. Un investitore di lungo termine dovrebbe fare poche operazioni all’anno. L’app ti mostrerà un contatore delle operazioni e ti avviserà se stai superando la media consigliata per il tuo profilo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(99, 153, 'Aspettare il momento perfetto per investire, o volere il portafoglio matematicamente ottimale, è una forma di procrastinazione. Non esiste il portafoglio perfetto, esiste quello che funziona per te e che riesci a mantenere nel tempo. L’app ti incoraggerà a iniziare con una soluzione semplice, migliorandola gradualmente, senza cercare l’impossibile.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(100, 154, 'La regola più semplice e più potente: se non capisci come funziona uno strumento, non comprarlo. Non importa se lo consiglia l’esperto, se ha reso bene in passato o se sembra innovativo. Solo ciò che comprendi può essere gestito con serenità. L’app ti farà questa domanda prima di ogni acquisto e, se rispondi “non lo so”, ti inviterà a studiare o a passare oltre.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(101, 161, 'Un’azione è una piccolissima quota di proprietà di un’azienda. Se compri un’azione Apple, diventi comproprietario, in proporzione. Il suo valore sale e scende in base agli utili e alle aspettative. Acquistare azioni singole però concentra il rischio: se l’azienda va male, perdi tutto. L’app ti spiegherà perché, per il lungo termine, è meglio possedere migliaia di aziende tramite ETF.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(102, 162, 'I dividendi sono una parte degli utili che l’azienda distribuisce agli azionisti. Non sono un regalo: quando vengono pagati, il valore dell’azione scende in proporzione. Un dividendo alto non è indice di solidità, a volte è sintomo di poca crescita. L’app ti mostrerà il dividend yield e ti aiuterà a capire che, nel lungo termine, conta di più la crescita totale (dividendi + aumento del prezzo).', '2026-05-08 20:52:04', NULL, NULL, 1),
	(103, 163, 'Il prezzo di un’azione non dipende solo dai risultati attuali, ma anche dalle aspettative future. Può essere molto volatile nel breve periodo. Per questo le azioni vanno tenute per almeno 10 anni, in modo da assorbire le oscillazioni. L’app ti mostrerà un grafico a lungo termine di un indice azionario, evidenziando i periodi di crisi e la successiva ripresa.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(104, 164, 'Storicamente l’azionario globale ha reso in media il 5-7% annuo sopra l’inflazione su periodi molto lunghi. Ma “medio” non significa “tutti gli anni”: ci sono stati decenni piatti e anni con -40%. L’app ti farà simulare diversi archi temporali, mostrandoti che investire con costanza riduce il rischio di beccare il momento peggiore.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(105, 165, 'Scegliere azioni singole richiede tempo, competenza e un po’ di fortuna. Anche i professionisti faticano a battere il mercato. Per un investitore che non fa della finanza la sua professione, è molto più efficiente comprare ETF diversificati. L’app ti sconsiglierà di dedicare più del 5-10% del patrimonio a scommesse su singole azioni, e solo se sei consapevole dei rischi.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(106, 166, 'Il rischio specifico è quello legato a una singola azienda: scandali, errori strategici, bancarotta. Si può eliminare diversificando. Un ETF su 1.000 aziende azzera quasi completamente questo rischio. L’app ti mostrerà, con un esempio, la differenza tra tenere un’azione sola e un indice: in caso di fallimento, nel primo perdi tutto, nel secondo quasi nulla.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(107, 167, 'Diversificare significa non mettere tutte le uova nello stesso paniere. In ambito azionario vuol dire comprare aziende di tanti paesi, settori e dimensioni. Un ETF MSCI World o FTSE All-World fa già questo lavoro per te. L’app ti aiuterà a costruire la parte azionaria del portafoglio con pochi ETF ben scelti, senza sovrapposizioni inutili.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(108, 168, 'Il motivo per cui l’azionario va tenuto 10 anni o più è statistico: in qualsiasi finestra mobile di 10 anni, la probabilità di perdita è molto bassa; in finestre di 1-2 anni, è alta. Se quei soldi ti serviranno prima, non puoi permetterti il rischio azionario. L’app ti chiederà l’orizzonte temporale e ti mostrerà la probabilità storica di guadagno o perdita per quella durata.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(109, 169, 'Il mercato azionario segue un percorso casuale nel breve, anche se nel lungo periodo è spinto dalla crescita economica. Chi dice di sapere se domani salirà o scenderà sta mentendo. L’unica strategia razionale è investire regolarmente e rimanere investiti. L’app ti ricorderà questa verità con una citazione o un dato ogni volta che apri la sezione portafoglio.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(110, 170, 'Paura ed euforia sono nemiche dell’investitore. La paura ti spinge a vendere sui minimi; l’euforia a comprare sui massimi. L’app ti invierà notifiche comportamentali: quando tutto sale, ti dirà di ricordare i cali passati; quando tutto scende, ti mostrerà i recuperi storici. L’obiettivo è tenere le emozioni fuori dalle decisioni finanziarie.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(111, 177, 'L’ETF (Exchange Traded Fund) è un fondo negoziato in borsa come un’azione, ma che replica un indice. È trasparente, economico e flessibile. A differenza dei fondi comuni attivi, non c’è un gestore che sceglie i titoli, ma una regola automatica. L’app ti mostrerà i vantaggi degli ETF rispetto ai fondi tradizionali: costi più bassi, maggiore diversificazione, semplicità.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(112, 178, 'La gestione passiva significa seguire il mercato, non cercare di batterlo. È come andare in bicicletta con il vento a favore invece di remare controcorrente. Accetti il rendimento medio, che nel lungo periodo ha battuto la maggior parte dei gestori attivi. L’app ti spiegherà perché il passivo è la scelta ideale per chi vuole costruire un patrimonio senza diventare un trader.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(113, 179, 'La gestione attiva punta a fare meglio del mercato scegliendo titoli o tempistiche. I costi sono più alti e, dopo le commissioni, la maggior parte dei fondi attivi sottoperforma l’indice di riferimento. Non è la scelta consigliata per chi segue il metodo semplice. L’app ti mostrerà un grafico di confronto tra fondi attivi e indice passivo su 10 anni: parlerà da solo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(114, 180, 'Ogni ETF replica un indice: una lista di titoli con determinate regole. L’indice può essere geografico (MSCI World), settoriale (tecnologia) o tematico (robotica). Ciò che conta è cosa c’è dentro, non il nome accattivante. L’app ti farà aprire sempre la “scheda indice” per vedere i primi 10 componenti e i pesi percentuali, prima di ogni acquisto.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(115, 181, 'Il costo corrente di un ETF è il TER (Total Expense Ratio), espresso in percentuale annua. Un TER dello 0,20% significa che paghi 2 euro ogni 1.000 investiti. Su 20 anni, la differenza tra 0,20% e 1,50% può erodere migliaia di euro. L’app ti mostrerà l’impatto dei costi sul montante finale, facendoti scegliere ETF efficienti.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(116, 182, 'La liquidità di un ETF non dipende solo dal volume di scambi, ma anche dalla liquidità dei titoli sottostanti. Un ETF ampio e con molti volumi è facilmente vendibile. L’app ti segnalerà gli ETF con volumi bassi o spread elevati, suggerendoti alternative più liquide, per evitare di pagare prezzi inefficienti in uscita.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(117, 183, 'Un solo ETF può contenere migliaia di azioni di decine di paesi, offrendo una diversificazione istantanea. Questo è il cuore del quarto pilastro: con 2-3 ETF globali puoi coprire tutto il mercato azionario. L’app ti aiuterà a comporre la parte azionaria con il minor numero di strumenti, evitando sovrapposizioni inutili.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(118, 184, 'La parte azionaria del portafoglio va pensata per il lunghissimo termine: 10, 15, 20 anni. Solo così si possono assorbire i momenti di crisi. L’app ti chiederà per ogni ETF azionario di impostare un orizzonte minimo e, se cerchi di venderlo prima, ti avviserà mostrando la volatilità residua.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(119, 185, 'Non serve comprare ETF su borse estere: su Borsa Italiana trovi centinaia di ETF conformi alla normativa UCITS e quotati in euro. Questo semplifica la fiscalità e riduce i costi di cambio. L’app per default ti mostrerà solo ETF negoziabili su mercati italiani, per tenere tutto semplice e sotto controllo.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(120, 186, 'La semplicità paga: un solo ETF azionario globale (es. VWCE o SWDA) può bastare per il quarto pilastro. Aggiungere complessità non aumenta il rendimento atteso, ma sicuramente lo stress. L’app ti proporrà un “portafoglio pigro” precompilato, che potrai personalizzare solo se hai esigenze specifiche e consapevoli.', '2026-05-08 20:52:04', NULL, NULL, 1),
	(121, 193, 'Gli indici geografici raggruppano aziende di una certa area: USA, Europa, Giappone, Mercati Emergenti. Attenzione: un ETF “Europa” può contenere soprattutto aziende multinazionali che operano in tutto il mondo. L’app ti mostrerà una mappa visiva della provenienza dei ricavi, non solo della sede legale, per capire l’esposizione reale.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(122, 194, 'Il MSCI World è l’indice di riferimento per i mercati sviluppati: circa 1.500 aziende di 23 paesi. Non include i mercati emergenti. È molto concentrato sugli USA (oltre il 70%). L’app ti spiegherà che “World” non significa globale, e ti suggerirà un indice All-Country World (ACWI) se vuoi coprire anche i paesi emergenti.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(123, 195, 'Cina, India, Brasile sono esempi di mercati emergenti: economie in crescita ma con rischi politici e di valuta più alti. Possono dare una marcia in più al portafoglio, ma con maggiore volatilità. L’app ti consiglierà di dedicare agli emergenti una quota limitata (10-15% dell’azionario) e sempre tramite ETF.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(124, 196, 'Un indice globale include sia mercati sviluppati che emergenti, pesati per capitalizzazione. È la soluzione “all-in-one” per chi vuole massima semplicità. Con un solo ETF copri l’intero mercato azionario mondiale. L’app ti mostrerà i principali ETF globali e le loro piccole differenze, per scegliere il più adatto.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(125, 197, 'Robotica, intelligenza artificiale, biotech: gli indici tematici scelgono aziende di un tema specifico, spesso con poca diversificazione e costi più alti. Possono essere molto volatili. L’app ti avviserà che investire in questi temi è più simile a una scommessa che a un pilastro solido, e ti suggerirà di mantenerli sotto il 5% del portafoglio totale.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(126, 198, 'Sanità, energia, tecnologia: gli indici settoriali raggruppano aziende di un solo settore. Anche qui la diversificazione è bassa e il rischio specifico resta elevato. L’app ti mostrerà la correlazione tra settori: spesso quelli che salgono oggi scendono domani, mentre un indice globale è più bilanciato.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(127, 199, 'La maggior parte degli indici è “value-weighted” (o “cap-weighted”): le aziende più grandi pesano di più. Questo significa che Apple e Microsoft influenzano l’indice molto più di decine di aziende piccole. L’app ti mostrerà la concentrazione nei primi 10 titoli, così saprai se il tuo ETF è troppo dipendente da poche società.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(128, 200, 'Un indice “equally weighted” dà lo stesso peso a tutte le aziende, indipendentemente dalla capitalizzazione. Riduce la concentrazione ma aumenta il turnover e i costi. L’app ti spiegherà che, per un investitore di lungo termine, l’approccio cap-weighted è più efficiente e storicamente ha reso allo stesso modo.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(129, 201, 'Molti indici “globali” hanno oltre il 60% di USA. Questo non è necessariamente un male, ma devi saperlo. Se vuoi ridurre la concentrazione geografica, puoi aggiungere un ETF Europa o Giappone. L’app ti mostrerà la ripartizione geografica del tuo portafoglio complessivo, considerando tutti gli ETF che possiedi.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(130, 202, 'Prima di comprare un ETF, apri sempre la pagina della composizione dell’indice: troverai i primi 10 titoli, i settori principali e le valute. Questa semplice abitudine ti evita di credere di comprare “tecnologia” e invece ritrovarti con banche e petrolio. L’app ti spingerà a fare questo controllo con un pulsante ben visibile.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(131, 209, 'UCITS è una “marchio” di sicurezza europeo: un ETF che lo rispetta segue regole rigide su diversificazione e liquidità. In parole povere, è un prodotto regolamentato e adatto agli investitori retail. L’app ti mostrerà questa certificazione nella scheda prodotto e ti avviserà se stai per acquistare un ETF non UCITS, spesso più rischioso.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(132, 210, 'Un ETF ad accumulo reinveste automaticamente i dividendi all’interno del fondo, senza versarteli. Questo massimizza l’interesse composto e semplifica la gestione fiscale, perché non dovrai dichiarare cedole. È la scelta ideale per il lungo termine. L’app ti consiglierà l’accumulo di default, a meno che tu non abbia bisogno di un flusso cedolare costante.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(133, 211, 'L’ETF a distribuzione paga i dividendi agli investitori, come una cedola periodica. Può essere utile per chi vuole un reddito integrativo, ma obbliga a reinvestire manualmente se si vuole l’interesse composto. Inoltre, ogni dividendo è tassato. L’app ti mostrerà la differenza netta tra accumulo e distribuzione su 20 anni, con le tue aliquote fiscali.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(134, 212, 'La replica totale (o fisica completa) significa che l’ETF possiede realmente tutti i titoli dell’indice nelle giuste proporzioni. È il metodo più trasparente e semplice, anche se a volte più costoso per indici molto vasti. L’app preferirà segnalarti ETF a replica totale quando disponibili, a parità di costi.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(135, 213, 'Con il campionamento (sampling) l’ETF acquista solo un sottoinsieme dei titoli dell’indice, cercando di replicarne l’andamento. È più economico per indici molto grandi, ma può introdurre un piccolo scostamento rispetto all’indice. L’app ti mostrerà il tracking error, cioè la differenza tra rendimento dell’ETF e rendimento dell’indice, per valutare l’efficienza del campionamento.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(136, 214, 'Un ETF sintetico non compra direttamente i titoli, ma utilizza derivati (swap) per replicare l’indice. Può essere molto preciso, ma introduce un rischio di controparte. L’app ti spiegherà i pro e i contro e, in generale, per il lungo termine suggerirà la replica fisica come più intuitiva e allineata al metodo semplice.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(137, 215, 'La dimensione del fondo (in milioni di euro) indica quanto è grande e consolidato l’ETF. Un fondo molto piccolo può avere bassi volumi, spread alti e rischiare di essere liquidato. L’app ti segnalerà una soglia minima (ad esempio 100 milioni) e ti metterà in guardia se scendi sotto quel limite.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(138, 216, 'Gli ETF monetari investono in strumenti del mercato monetario a brevissimo termine (es. overnight). Sono un’alternativa al conto deposito per parcheggiare liquidità in attesa di investimenti. L’app ti mostrerà il rendimento atteso, i costi e la volatilità quasi nulla, aiutandoti a decidere se usarli per il fondo di emergenza o per la liquidità in eccesso.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(139, 217, 'ETC (Exchange Traded Commodities) replicano materie prime come oro o petrolio. ETN sono note strutturate con rischio emittente. Non sono ETF UCITS e vanno maneggiati con cura. Per un investitore di lungo termine, l’oro può avere un piccolo ruolo, ma il resto è evitabile. L’app li collocherà in una categoria separata, chiedendo conferma prima dell’acquisto.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(140, 218, 'Prima di comprare un ETF, l’app ti farà spuntare una checklist: UCITS, TER, dimensione del fondo, replica (fisica o sintetica), accumulo/distribuzione, liquidità e spread. Solo se tutti i parametri sono accettabili ti darà via libera. Questa semplice routine ti proteggerà da acquisti affrettati e da prodotti inadatti.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(141, 225, 'Due strumenti sono correlati positivamente se tendono a salire e scendere insieme; negativamente se si muovono in direzioni opposte. In portafoglio, vorresti asset con bassa correlazione, così quando uno scende l’altro può salire. L’app ti mostrerà una matrice di correlazione semplificata tra le tue posizioni, per capire se sei davvero diversificato.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(142, 226, 'Diversificare non significa comprare tanti prodotti, ma distribuire il rischio su asset diversi per comportamento: azioni globali, obbligazioni a breve, oro, liquidità. L’app ti mostrerà l’asset allocation attuale con un grafico a torta e ti avviserà se sei troppo concentrato su una singola categoria.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(143, 227, 'Prima di definire le percentuali, chiediti: quanto sei disposto a perdere in un anno senza andare nel panico? Questa è la tua massima perdita tollerabile. Da qui si decide la quota azionaria. L’app ti farà un piccolo test di tolleranza al rischio e poi ti proporrà un’allocazione coerente.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(144, 228, 'La percentuale da investire in azioni è il motore del rendimento di lungo termine, ma anche della volatilità. Una regola pratica è 100 meno l’età, oppure basarsi sul test di rischio. L’app ti suggerirà un intervallo (es. 60-80% per un trentenne) e ti aiuterà a scegliere il punto esatto in base al tuo sonno tranquillo.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(145, 229, 'La parte obbligazionaria serve a stabilizzare il portafoglio e a fornire liquidità per le spese prevedibili. Non deve essere rischiosa: meglio titoli di Stato a breve termine o ETF obbligazionari governativi con duration contenuta. L’app ti consiglierà una componente obbligazionaria adatta alla tua età e ai tuoi obiettivi a medio termine.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(146, 230, 'Dove investire geograficamente? Se hai un ETF globale, sei già esposto a tutto il mondo. Se vuoi sovrappesare una regione, fallo con cognizione: ad esempio, un’Europa più pesata può ridurre il rischio di cambio. L’app ti mostrerà una mappa mondiale con l’esposizione attuale del tuo portafoglio, calcolata in base ai ricavi, non solo alla sede legale.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(147, 231, 'Le large cap sono le aziende più grandi e conosciute; le small cap sono aziende più piccole, potenzialmente più redditizie ma più volatili. Un ETF globale le include già entrambe nella giusta proporzione. L’app ti spiegherà che, se vuoi aggiungere un extra di small cap, puoi farlo con un ETF specifico, ma senza esagerare: un 10% dell’azionario può bastare.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(148, 232, 'Una volta scelta l’allocazione, resisti alla tentazione di modificarla ogni volta che un asset va meglio dell’altro. È il cosiddetto “performance chasing” e di solito peggiora i risultati. L’app ti invierà un alert se stai per cambiare troppo spesso, mostrandoti il rendimento che avresti ottenuto rimanendo fermo.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(149, 233, 'Col tempo, le proporzioni del tuo portafoglio cambiano: le azioni crescono di più, le obbligazioni restano indietro. Ribilanciare significa riportarle ai pesi originali, vendendo un po’ di ciò che è salito e comprando ciò che è sceso. È una strategia disciplinata che riduce il rischio. L’app ti suggerirà quando ribilanciare, ad esempio una volta all’anno o quando lo scostamento supera il 5%.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(150, 234, 'Non guardare il rendimento di un singolo anno, non confrontarti con il portafoglio di un amico, non farti influenzare dai titoli dei telegiornali. Concentrati sul tuo piano. L’app ti offrirà una vista “essenziale” che mostra solo l’asset allocation e il rendimento annualizzato dal tuo inizio, oscurando i dettagli inutili.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(151, 241, 'Il portafoglio perfetto non esiste: esiste quello adatto a te. Età, stabilità lavorativa, obiettivi a breve e lungo, propensione al rischio e situazione familiare sono i fattori che contano. L’app ti proporrà alcuni profili tipo (giovane, famiglia, pre-pensionamento) e ti guiderà a personalizzarli con i tuoi dati.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(152, 242, 'Più sei giovane e con reddito stabile, più puoi permetterti una quota azionaria alta, perché hai tempo per recuperare le perdite. Con l’avanzare dell’età o con lavori precari, la quota obbligazionaria o liquida deve salire per proteggerti. L’app ti farà un quiz sull’età e sulla stabilità del tuo lavoro per calibrare l’allocazione.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(153, 243, 'Se hai figli o progetti di acquisto casa, questi obiettivi vanno separati e parcheggiati nel terzo pilastro. Non puoi usare il fondo pensione o l’azionario per la retta scolastica tra tre anni. L’app ti farà elencare gli obiettivi familiari con data e importo stimato, e costruirà il terzo pilastro dedicato.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(154, 244, 'L’acquisto casa o auto è un obiettivo concreto, con una data e un importo definito. Va finanziato con risparmio accumulato nel terzo pilastro, non con l’azionario. L’app ti aiuterà a calcolare quanto accantonare ogni mese per raggiungere la cifra entro la data desiderata, usando strumenti obbligazionari adeguati.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(155, 245, 'Se hai 30 anni e pianifichi la pensione, hai un orizzonte di oltre 30 anni. In questo caso puoi permetterti un 80-100% di azionario globale per i primi 15-20 anni. L’app ti mostrerà come evolve il portafoglio nel tempo con un “glide path”: più ti avvicini alla data, più riduci l’azionario.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(156, 246, 'Se vedere il portafoglio in rosso ti toglie il sonno, la tua allocazione è troppo aggressiva, anche se l’orizzonte sarebbe favorevole. La psicologia conta più della matematica. L’app ti offrirà la possibilità di abbassare la volatilità anche a costo di un minor rendimento atteso, per la tua tranquillità.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(157, 247, 'Se hai già un patrimonio consistente, puoi permetterti un’allocazione più conservativa, perché hai meno bisogno di rincorrere rendimenti elevati. L’app ti mostrerà come il tuo capitale attuale può bastare anche con percentuali azionarie moderate, proteggendoti da grandi oscillazioni.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(158, 248, 'Chi ha poco capitale può comunque iniziare con un PAC (piano di accumulo) mensile. La costanza batte il capitale iniziale: 100 euro al mese per 20 anni diventano una cifra rispettabile. L’app ti incoraggerà a partire con piccole somme e a mantenere un’allocazione efficiente, senza pensare che servano grandi capitali iniziali.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(159, 249, 'Copiare il portafoglio di un amico o di un guru è come indossare le scarpe di un’altra persona: probabilmente non ti calzano. Ognuno ha obiettivi, vincoli e tolleranze diverse. L’app ti offrirà esempi ispirazionali, ma poi ti guiderà a creare il tuo, con i tuoi numeri.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(160, 250, 'La vita cambia: un nuovo lavoro, un figlio, una eredità. L’allocazione va rivista quando cambiano i bisogni, non quando cambia il mercato. L’app ti invierà un promemoria annuale per verificare se il tuo profilo è ancora valido o se è il momento di aggiornarlo.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(161, 257, 'L’imposta di bollo colpisce sia il conto corrente (oltre 5.000€ di giacenza media) sia il conto titoli (0,2% annuo sul valore dei titoli). Non è enorme, ma su patrimoni importanti può pesare. L’app ti mostrerà l’impatto di questa tassa sul rendimento netto del tuo portafoglio, così non la dimenticherai.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(162, 258, 'Sono redditi da capitale le cedole, i dividendi e gli interessi. In Italia sono tassati al 26% (o 12,5% per i titoli di Stato). Le tasse vengono solitamente trattenute alla fonte dal tuo intermediario se sei in regime amministrato. L’app ti mostrerà sempre il rendimento netto dopo questa tassazione, perché è ciò che conta davvero.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(163, 259, 'I redditi diversi sono le plusvalenze (capital gain) da vendita di strumenti finanziari. Anche queste sono tassate al 26%, ma solo al momento della vendita. Qui entrano in gioco le minusvalenze, che possono compensare le plusvalenze entro 4 anni. L’app ti aiuterà a tenere traccia delle minusvalenze utilizzabili per ridurre le future tasse.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(164, 260, 'Se vendi uno strumento in perdita, generi una minusvalenza che puoi usare per compensare future plusvalenze (non cedole o dividendi) entro 4 anni. È un meccanismo utile, ma non vendere apposta in perdita solo per creare minusvalenze: sarebbe un errore. L’app ti segnalerà le minusvalenze accumulate e la loro scadenza, per sfruttarle al meglio.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(165, 261, 'Nel regime amministrato, l’intermediario fa da sostituto d’imposta: liquida le tasse per te e tu non devi dichiarare nulla. È la scelta più semplice e consigliata per evitare errori. L’app ti consiglierà sempre un conto titoli in regime amministrato, a meno che tu non abbia esigenze particolari e un commercialista al tuo fianco.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(166, 262, 'Con il regime dichiarativo, l’intermediario ti fornisce un report, ma sei tu a dover compilare la dichiarazione dei redditi (quadro RW, RT, RL). Se sbagli rischi sanzioni. L’app sconsiglierà questo regime a meno che tu non abbia una solida conoscenza fiscale o un commercialista che ti segue.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(167, 263, 'Nel regime gestito (come le gestioni patrimoniali), il gestore fa tutto, ma i costi sono alti e la fiscalità non ti permette di compensare plusvalenze con minusvalenze tra diversi rapporti. Raramente conviene. L’app ti mostrerà un confronto tra i tre regimi, mettendo in evidenza costi e benefici per il tuo caso specifico.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(168, 264, 'Gli ETF armonizzati (UCITS) sono tassati al 26% su plusvalenze e dividendi (o 12,5% se investono prevalentemente in titoli di Stato). La tassazione è semplice in regime amministrato. L’app applica automaticamente l’aliquota corretta per ogni ETF che inserisci nel portafoglio.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(169, 265, 'L’Italia applica una piccola tassa sulle transazioni di azioni italiane (Tobin tax). Sugli ETF è praticamente nulla, ma esiste. L’app la considererà nei calcoli dei costi di transazione, anche se il suo impatto è trascurabile per un investitore a lungo termine che fa poche operazioni.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(170, 266, 'Il rendimento netto è l’unico che devi guardare: lordo meno tasse, meno costi di gestione, meno imposta di bollo. L’app calcolerà il tuo rendimento netto annualizzato complessivo, così potrai valutare se il tuo portafoglio sta lavorando come previsto, senza illusioni da numeri lordi.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(171, 273, 'Il book è il tabellone dove compaiono tutte le proposte di acquisto (bid) e vendita (ask) con prezzi e quantità. Guardare il book prima di inserire un ordine ti dice se c’è abbastanza liquidità e a che prezzo puoi realisticamente chiudere l’operazione. L’app ti mostrerà un book semplificato e ti spiegherà come leggerlo in pochi secondi.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(172, 274, 'Il bid è il prezzo massimo a cui qualcuno è disposto a comprare. Se vuoi vendere subito al meglio, incasserai circa il prezzo bid. L’app ti farà capire che vendere “al meglio” significa prendere il bid più alto presente sul book in quel momento.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(173, 275, 'L’ask è il prezzo minimo a cui qualcuno è disposto a vendere. Se vuoi comprare subito al meglio, pagherai circa il prezzo ask. La differenza tra ask e bid è lo spread. L’app ti mostrerà sempre questi due valori prima di inserire un ordine di acquisto.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(174, 276, 'Lo spread è la forchetta tra prezzo bid e ask. Più è piccolo, più lo strumento è liquido e meno paghi di costo implicito. Per ETF molto liquidi, lo spread può essere di pochi centesimi; per obbligazioni poco scambiate, può essere molto più ampio. L’app ti segnalerà se lo spread supera una certa soglia, suggerendo prudenza o l’uso di un ordine limitato.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(175, 277, 'All’apertura della borsa c’è un’asta di apertura: gli ordini accumulati vengono incrociati a un prezzo unico. In questo momento la volatilità può essere alta. L’app ti consiglierà di evitare di inserire ordini al meglio nei primi minuti di borsa, a meno che tu non abbia molta fretta.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(176, 278, 'Con l’ordine limitato decidi tu il prezzo massimo (se compri) o minimo (se vendi). Se il mercato non raggiunge quel prezzo, l’ordine non viene eseguito. È lo strumento giusto per evitare sorprese su strumenti poco liquidi. L’app ti suggerirà di usarlo come impostazione predefinita per tutti i tuoi investimenti, con un prezzo limite ragionevole vicino all’ask/bid corrente.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(177, 279, 'L’ordine al meglio (a mercato) esegue subito l’operazione al miglior prezzo disponibile in quel momento. Veloce ma rischioso: su titoli poco liquidi potresti pagare molto più del previsto. L’app ti chiederà conferma se stai per usare un ordine al meglio su uno strumento con spread superiore all’1%.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(178, 280, 'L’ordine “esegui e cancella” (immediate-or-cancel) esegue subito la parte disponibile e cancella il resto. Utile se vuoi comprare una certa quantità ma sei disposto a prenderla solo se completamente eseguibile. L’app non lo proporrà per operazioni standard, ma lo spiegherà per completezza.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(179, 281, 'Un grande ordine può essere “nascosto” mostrando solo una piccola parte alla volta (iceberg). Serve agli istituzionali per non muovere il mercato. Per te, piccolo investitore, non serve quasi mai. L’app non lo abiliterà, ma ti farà sapere che esiste.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(180, 282, 'Anche in chiusura c’è un’asta, con dinamiche simili all’apertura. I prezzi possono variare rapidamente. L’app ti avviserà se inserisci un ordine negli ultimi minuti di negoziazione, suggerendoti di posticipare di qualche minuto o di usare un limite.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(181, 289, 'Se un titolo viene sospeso, non puoi venderlo per un certo periodo. Succede per comunicazioni importanti o eccesso di volatilità. Non è un dramma per un investitore di lungo termine. L’app ti spiegherà cosa significa e ti inviterà alla calma, mostrandoti che di solito la sospensione dura poche ore o giorni.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(182, 290, 'Il delisting è quando un titolo esce dalla borsa. Se possiedi azioni, potresti ricevere un’offerta di acquisto o trovarti con un titolo illiquido. È un evento raro. L’app ti segnalerà se uno strumento nel tuo portafoglio viene delistato e ti guiderà su come comportarti (accettare l’offerta o attendere).', '2026-05-08 20:52:05', NULL, NULL, 1),
	(183, 291, 'L’IPO è l’offerta pubblica iniziale: un’azienda si quota per la prima volta. Spesso c’è molto entusiasmo, ma le IPO sono storicamente un cattivo affare per i piccoli investitori. L’app ti consiglierà di evitare di partecipare alle IPO e di aspettare che il titolo venga incluso in un indice, comprandolo poi tramite ETF.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(184, 292, 'Uno split azionario moltiplica il numero di azioni e divide il prezzo in proporzione. Non cambia il valore totale del tuo investimento. L’app te lo segnalerà per evitare che tu pensi di aver guadagnato o perso qualcosa: è solo un’operazione contabile.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(185, 293, 'Il raggruppamento (reverse split) riduce il numero di azioni e aumenta il prezzo unitario. Come lo split, non cambia il valore complessivo. L’app ti mostrerà il tuo portafoglio già aggiornato per non creare confusione.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(186, 294, 'La liquidità di un titolo indica quanto facilmente puoi comprare o vendere senza muovere il prezzo. Per un investitore di lungo termine in ETF molto scambiati, la liquidità è raramente un problema. L’app ti avviserà solo se detieni strumenti con volumi medi giornalieri molto bassi.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(187, 295, 'Le aziende quotate pubblicano regolarmente comunicati (utili, assemblee, acquisizioni). Non devi leggerli tutti: se possiedi un ETF, il gestore fa già questo lavoro. L’app non ti bombarderà di notizie, ma ti segnalerà solo eventi straordinari come aumenti di capitale o OPA che potrebbero richiedere una tua azione.', '2026-05-08 20:52:05', NULL, NULL, 1),
	(188, 296, 'Il prezzo teorico (o NAV per gli ETF) è il valore calcolato in base ai prezzi dei componenti. A volte il prezzo di borsa se ne discosta leggermente. L’app ti mostrerà la differenza percentuale, rassicurandoti che piccoli scostamenti sono normali e temporanei grazie al meccanismo degli arbitraggisti.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(189, 297, 'Il rischio operativo riguarda errori di esecuzione, problemi tecnici della banca, ritardi nei bonifici. Puoi ridurlo usando intermediari solidi e tenendo sempre un buffer di liquidità. L’app ti suggerirà di non eseguire operazioni urgenti all’ultimo minuto e di salvare le ricevute degli ordini.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(190, 298, 'Vendere su mercato significa emettere un ordine di vendita in borsa. Per ETF liquidi, la vendita al meglio è quasi istantanea. Per strumenti meno liquidi, meglio un ordine limitato. L’app ti guiderà nella scelta del tipo di ordine in base allo strumento che stai vendendo.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(191, 305, 'Il fondo pensione è uno strumento per costruire una rendita integrativa alla pensione pubblica. Puoi versare contributi volontari, deducendoli dal reddito IRPEF fino a circa 5.100 euro annui. Tuttavia, i soldi sono vincolati fino alla pensione, salvo casi particolari. L’app ti aiuterà a valutare se e quanto destinare al fondo pensione in base al tuo profilo fiscale e ai tuoi obiettivi.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(192, 306, 'I contributi versati al fondo pensione vengono dedotti dal reddito imponibile: significa che paghi meno IRPEF oggi. Il vantaggio è immediato, ma dovrai pagare le tasse sulla prestazione finale, con aliquote agevolate. L’app ti farà simulare il risparmio fiscale annuo in base alla tua aliquota marginale, così potrai decidere consapevolmente.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(193, 307, 'Se sei un lavoratore dipendente, il tuo datore di lavoro può versare un contributo aggiuntivo al fondo pensione (di solito collegato al tuo versamento, come l’1-2% della retribuzione). È denaro gratis: non devi rinunciarci. L’app ti ricorderà di verificare le condizioni del tuo contratto e di versare almeno il minimo per ottenere il contributo datoriale.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(194, 308, 'I rendimenti del fondo pensione sono tassati al 20% (invece del 26%) e la tassazione scende con gli anni di permanenza fino al 9%. Inoltre non si paga imposta di bollo. Questo rende il fondo pensione fiscalmente molto efficiente per il lungo termine. L’app ti mostrerà un confronto tra un investimento nel fondo pensione e lo stesso investimento in ETF fuori dal fondo, calcolando il netto dopo molti anni.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(195, 309, 'Sui fondi pensione non si paga l’imposta di bollo annuale dello 0,2% che colpisce il conto titoli. Su patrimoni consistenti e lunghi periodi, il risparmio è significativo. L’app lo includerà nel confronto tra investimento nel fondo e investimento diretto.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(196, 310, 'Il principale svantaggio del fondo pensione è che i soldi sono bloccati fino all’età pensionabile, con poche eccezioni (spese sanitarie, prima casa, disoccupazione). Se hai bisogno di flessibilità, non versare più della soglia che ti fa dormire sonni tranquilli. L’app ti farà simulare cosa succede se devi attingere a quei fondi prima della scadenza, mostrando le penalità.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(197, 311, 'Al momento del pensionamento, puoi ricevere il montante come rendita mensile o, in parte, come capitale. La scelta dipende dalle tue esigenze. L’app ti farà riflettere su pro e contro di ogni opzione: la rendita protegge il rischio di longevità, il capitale ti dà flessibilità immediata.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(198, 312, 'I fondi pensione hanno costi di gestione annuali (ISC), che possono variare dallo 0,5% al 2% e più. Un costo alto erode il vantaggio fiscale. L’app ti aiuterà a scegliere il fondo pensione con l’ISC più basso tra quelli disponibili per il tuo profilo, perché ogni punto percentuale conta sulla lunga distanza.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(199, 313, 'Il fondo pensione conviene soprattutto se hai un’aliquota IRPEF alta, se ricevi il contributo del datore di lavoro e se riesci a tenere i soldi vincolati fino alla pensione senza ansie. Se guadagni poco o hai bisogno di liquidità a breve, potrebbe non essere la priorità. L’app ti farà un check-up personalizzato per capire se, nel tuo caso, il gioco vale la candela.', '2026-05-08 20:52:06', NULL, NULL, 1),
	(200, 314, 'La previdenza complementare non sostituisce il quarto pilastro, ma lo affianca. Puoi avere un fondo pensione per la parte più fiscale e un portafoglio ETF per la parte più flessibile. L’app ti aiuterà a decidere la ripartizione ottimale tra i due strumenti, considerando vincoli, costi e benefici fiscali.', '2026-05-08 20:52:06', NULL, NULL, 1);
