INSERT INTO `modules` (`id_module`, `description`, `name`, `created_at`, `last_update`, `id_user`, `active`) VALUES
	(1, 'Impostare le basi: investimento non speculativo, rischio a fine periodo, semplicità e metodo', 'Metodo e obiettivi', '2026-05-08 20:52:02', '2026-05-08 23:24:36', 1, 1),
	(2, 'Organizzare il patrimonio in liquidità, fondo emergenza, spese prevedibili e lungo termine.', 'Strategia a quattro pilastri', '2026-05-08 20:52:02', NULL, NULL, 1),
	(3, 'Gestire il primo pilastro: conto corrente, conto secondario, carte conto e trasferimento.', 'Liquidità e conto corrente', '2026-05-08 20:52:02', NULL, NULL, 1),
	(4, 'Distinguere carta di debito, credito e ricaricabile, costi, massimale e uso corretto.', 'Carte di pagamento', '2026-05-08 20:52:02', NULL, NULL, 1),
	(5, 'Capire conto titoli, mercati accessibili, commissioni, intermediari italiani ed esteri.', 'Conto titoli e intermediari', '2026-05-08 20:52:02', NULL, NULL, 1),
	(6, 'Rendimento, interesse composto, annualizzazione e flussi di cassa applicati a casi pratici.', 'Matematica finanziaria base', '2026-05-08 20:52:02', NULL, NULL, 1),
	(7, 'Costruire e collocare il secondo pilastro tra conto, deposito, BOT, BTP brevi ed ETF monetari.', 'Fondo di emergenza', '2026-05-08 20:52:02', NULL, NULL, 1),
	(8, 'Usare il terzo pilastro per obiettivi da uno a dieci anni tramite strumenti a scadenza.', 'Spese previste e obbligazioni', '2026-05-08 20:52:02', NULL, NULL, 1),
	(9, 'Prezzo, tassi, aziende, rateo, valuta e attenzione alla microstruttura quando si compra.', 'Acquisto di obbligazioni', '2026-05-08 20:52:02', NULL, NULL, 1),
	(10, 'Evitare promesse di garanzia, polizze, strumenti complessi, timing di mercato e movimenti inutili.', 'Errori da evitare', '2026-05-08 20:52:02', NULL, NULL, 1),
	(11, 'Capire azioni, dividendi, prezzo, rendimento medio e perché evitare singoli titoli casuali.', 'Azioni e dividendi', '2026-05-08 20:52:02', NULL, NULL, 1),
	(12, 'Usare ETF e indici per il quarto pilastro, distinguendo gestione attiva e passiva.', 'ETF azionari', '2026-05-08 20:52:03', NULL, NULL, 1),
	(13, 'Leggere indici geografici, tematici e settoriali senza confondere nome e diversificazione reale.', 'Indici e mercati', '2026-05-08 20:52:03', NULL, NULL, 1),
	(14, 'UCITS, accumulo, distribuzione, replica, dimensione del fondo, ETF monetari, ETC, ETN.', 'Dettagli ETF ed ETP', '2026-05-08 20:52:03', NULL, NULL, 1),
	(15, 'Costruire il portafoglio con diversificazione, correlazione, rischio massimo e ribilanciamento.', 'Asset allocation', '2026-05-08 20:52:03', NULL, NULL, 1),
	(16, 'Applicare i concetti a profili diversi: età, stabilità, obiettivi, ansia e patrimonio.', 'Portafogli esempio', '2026-05-08 20:52:03', NULL, NULL, 1),
	(17, 'Imposta di bollo, redditi da capitale, redditi diversi, minusvalenze e regimi fiscali.', 'Tassazione investimenti', '2026-05-08 20:52:03', NULL, NULL, 1),
	(18, 'Capire book, apertura, spread bid-ask, ordini limitati, ordini al meglio e chiusura.', 'Microstruttura dei mercati', '2026-05-08 20:52:03', NULL, NULL, 1),
	(19, 'Sospensione, delisting, IPO, split, raggruppamento e conseguenze operative.', 'Eventi di mercato', '2026-05-08 20:52:03', NULL, NULL, 1),
	(20, 'Comprendere fondo pensione, deducibilità, contributo datore, tassazione, vincoli e costi.', 'Fondo pensione', '2026-05-08 20:52:03', NULL, NULL, 1);
